LB.historias = [
{id:'historia-01',titulo:'O gato que perdeu o chapéu',autor:'Domínio público',anoEscolar:2,habilidadesBNCC:['EF02LP26','EF02LP03'],nivel:1,emoji:'🐱',corFundo:'linear-gradient(135deg,#ffe0e0,#ffe8cc)',texto:['Era uma vez um gato cinza chamado Tobias.','Um dia, ele perdeu seu chapéu vermelho.','Tobias procurou na cozinha, no quintal e embaixo da cama.','Foi quando viu o chapéu na cabeça do espantalho.','Tobias subiu no espantalho com cuidado e pegou seu chapéu de volta.','E voltou para casa feliz, com o chapéu bem firme na cabeça.'],perguntas:[{tipo:'multipla',enunciado:'Qual é a cor do chapéu do Tobias?',opcoes:['Azul','Vermelho','Verde'],correta:1,explicacao:'O texto diz "seu chapéu vermelho".'},{tipo:'multipla',enunciado:'Onde Tobias encontrou o chapéu?',opcoes:['Na cozinha','No quintal','Na cabeça do espantalho'],correta:2,explicacao:'O texto mostra que ele viu o chapéu no espantalho.'},{tipo:'inferencia',enunciado:'Por que Tobias procurou em vários lugares?',opcoes:['Porque queria brincar','Porque havia perdido o chapéu','Porque estava com fome'],correta:1,explicacao:'Ele estava procurando o chapéu que tinha perdido.'}]},
{id:'historia-02',titulo:'A menina e a estrela',autor:'Domínio público',anoEscolar:2,habilidadesBNCC:['EF02LP26','EF15LP04'],nivel:1,emoji:'⭐',corFundo:'linear-gradient(135deg,#e0ecff,#f0e0ff)',texto:['Lia era uma menina que adorava olhar o céu à noite.','Uma vez, ela viu uma estrela que parecia piscar só para ela.','Lia fez um pedido: queria um amigo para brincar.','No dia seguinte, uma menina nova chegou na escola.','As duas logo ficaram amigas e brincaram a tarde inteira.','Lia sorriu, pensando que a estrela tinha escutado seu pedido.'],perguntas:[{tipo:'multipla',enunciado:'O que Lia mais gostava de fazer?',opcoes:['Correr no parque','Olhar o céu à noite','Desenhar'],correta:1,explicacao:'O texto diz que ela adorava olhar o céu à noite.'},{tipo:'inferencia',enunciado:'Por que Lia sorriu no final?',opcoes:['Porque ganhou um brinquedo','Porque achou que o pedido se realizou','Porque viu outra estrela'],correta:1,explicacao:'Ela sorriu porque achou que a estrela tinha escutado seu pedido.'},{tipo:'multipla',enunciado:'O que Lia pediu à estrela?',opcoes:['Um brinquedo novo','Um amigo para brincar','Um caderno'],correta:1,explicacao:'O texto diz "queria um amigo para brincar".'}]},
{id:'historia-03',titulo:'A chuva que virou brincadeira no quintal',autor:'Domínio público',anoEscolar:2,habilidadesBNCC:['EF02LP26','EF15LP03'],nivel:2,emoji:'🌧️',corFundo:'linear-gradient(135deg,#d8e8f0,#c8d8e8)',texto:['Depois do almoço, o céu escureceu de repente e começou a cair uma chuva fina sobre o quintal.','Em vez de ficar emburrada por não poder sair para a rua, Marina pegou uma bacia velha, alguns potes de plástico e um pedaço de barbante.','Ela colocou a bacia no meio do quintal para ver quanto tempo levava para encher e fez barquinhos de papel para testar na água que escorria pelo chão de cimento.','Quando a chuva acalmou, ela chamou o primo para ajudar a guardar tudo e contou quantos potes tinham ficado cheios.','No fim da tarde, os dois sentaram na varanda com um lanche quentinho e combinaram de anotar no dia seguinte o que tinham descoberto.'],perguntas:[{tipo:'multipla',enunciado:'O que Marina colocou no meio do quintal?',opcoes:['Uma bacia','Uma bola','Uma cadeira'],correta:0,explicacao:'Ela colocou a bacia no meio do quintal para ver quanto tempo levava para encher.'},{tipo:'multipla',enunciado:'O que Marina fez para testar na água que escorria?',opcoes:['Desenhou no chão','Barquinhos de papel','Uma pipa'],correta:1,explicacao:'Ela fez barquinhos de papel para testar na água.'},{tipo:'inferencia',enunciado:'Como Marina reagiu à chuva?',opcoes:['Ficou emburrada o dia todo','Foi dormir','Transformou a chuva em brincadeira'],correta:2,explicacao:'Em vez de ficar emburrada, ela inventou brincadeiras com a chuva.'}]},
{id:'historia-04',titulo:'O passarinho corajoso',autor:'Domínio público',anoEscolar:2,habilidadesBNCC:['EF02LP26','EF15LP04'],nivel:2,emoji:'🐦',corFundo:'linear-gradient(135deg,#e8f5e0,#d0e8d8)',texto:['Tico era um passarinho pequeno, mas muito corajoso.','Um dia, uma tempestade o surpreendeu longe do ninho.','Todos os outros pássaros se esconderam.','Tico voou alto, enfrentando o vento, e encontrou um abrigo seguro.','Depois da tempestade, Tico guiou os outros pássaros até o abrigo.','Todos agradeceram ao pequeno herói.'],perguntas:[{tipo:'multipla',enunciado:'Como era Tico?',opcoes:['Grande e forte','Pequeno e corajoso','Tímido e lento'],correta:1,explicacao:'O texto diz "pequeno, mas muito corajoso".'},{tipo:'multipla',enunciado:'O que Tico encontrou durante a tempestade?',opcoes:['Um ninho novo','Um abrigo seguro','Um amigo'],correta:1,explicacao:'O texto diz que ele encontrou um abrigo seguro.'},{tipo:'inferencia',enunciado:'Por que todos agradeceram a Tico?',opcoes:['Porque ele cantou bonito','Porque ele os guiou até o abrigo','Porque ele trouxe comida'],correta:1,explicacao:'Ele guiou os outros pássaros até o abrigo após a tempestade.'}]},
{id:'historia-05',titulo:'A horta da vovó',autor:'Domínio público',anoEscolar:2,habilidadesBNCC:['EF02LP26','EF15LP03'],nivel:2,emoji:'🌱',corFundo:'linear-gradient(135deg,#e0f0d0,#f5e8c8)',texto:['Marina adorava passar os sábados na casa da vovó.','A vovó tinha uma horta com tomates, alfaces e cenouras.','Um dia, Marina perguntou como as plantas cresciam.','A vovó explicou que era preciso terra, água e sol.','Marina plantou uma sementinha e cuidou dela toda semana.','Depois de um mês, uma pequena cenoura apareceu.'],perguntas:[{tipo:'multipla',enunciado:'O que tinha na horta da vovó?',opcoes:['Flores e rosas','Tomates, alfaces e cenouras','Bananas e maçãs'],correta:1,explicacao:'O texto lista tomates, alfaces e cenouras.'},{tipo:'multipla',enunciado:'O que era preciso para as plantas crescerem?',opcoes:['Terra, água e sol','Vento e areia','Só água'],correta:0,explicacao:'A vovó explicou que era preciso terra, água e sol.'},{tipo:'inferencia',enunciado:'O que Marina aprendeu com a vovó?',opcoes:['A cozinhar','A cuidar de plantas','A desenhar'],correta:1,explicacao:'Ela aprendeu a cuidar de plantas, plantando e regando.'}]},
{id:'historia-06',titulo:'O menino e o peixe',autor:'Domínio público',anoEscolar:2,habilidadesBNCC:['EF02LP26','EF15LP04'],nivel:1,emoji:'🐟',corFundo:'linear-gradient(135deg,#d0e8ff,#e0f0ff)',texto:['Lucas foi pescar com o avô no rio.','Depois de esperar muito, ele fisgou um peixe pequeno.','O avô explicou que peixes pequenos precisam crescer.','Lucas devolveu o peixe à água com cuidado.','No fim do dia, ele voltou para casa feliz, mesmo sem peixe.'],perguntas:[{tipo:'multipla',enunciado:'Com quem Lucas foi pescar?',opcoes:['Com o pai','Com o avô','Com o irmão'],correta:1,explicacao:'O texto diz "foi pescar com o avô".'},{tipo:'multipla',enunciado:'O que Lucas fisgou?',opcoes:['Um peixe grande','Um peixe pequeno','Uma bota velha'],correta:1,explicacao:'Ele fisgou um peixe pequeno.'},{tipo:'inferencia',enunciado:'Por que Lucas devolveu o peixe?',opcoes:['Porque não gostou','Porque o peixe era pequeno e precisava crescer','Porque o avô mandou'],correta:1,explicacao:'O avô explicou que peixes pequenos precisam crescer.'}]},
{id:'historia-07',titulo:'A formiga trabalhadora',autor:'Domínio público',anoEscolar:2,habilidadesBNCC:['EF02LP26','EF15LP04'],nivel:1,emoji:'🐜',corFundo:'linear-gradient(135deg,#f0e0d0,#ffe8d0)',texto:['Dona Formiga trabalhava todos os dias, carregando folhas.','As outras formigas perguntavam por que ela não descansava.','Ela respondia: \"Quando a chuva chegar, teremos comida guardada.\"','Um dia, a chuva caiu por vários dias.','Todas as formigas ficaram quentinhas e alimentadas no formigueiro.'],perguntas:[{tipo:'multipla',enunciado:'O que Dona Formiga carregava?',opcoes:['Pedras','Folhas','Flores'],correta:1,explicacao:'O texto diz que ela carregava folhas.'},{tipo:'inferencia',enunciado:'Por que ela trabalhava todos os dias?',opcoes:['Porque gostava de andar','Para guardar comida para a chuva','Porque não tinha amigos'],correta:1,explicacao:'Ela queria ter comida guardada quando a chuva chegasse.'},{tipo:'multipla',enunciado:'O que aconteceu no fim?',opcoes:['Ficaram com fome','Ficaram alimentadas e quentinhas','Saíram do formigueiro'],correta:1,explicacao:'Todas ficaram quentinhas e alimentadas.'}]},
{id:'historia-08',titulo:'O dia do circo',autor:'Domínio público',anoEscolar:2,habilidadesBNCC:['EF02LP26','EF15LP03'],nivel:1,emoji:'🎪',corFundo:'linear-gradient(135deg,#ffe0e8,#fff0e0)',texto:['Bia nunca tinha ido ao circo.','No sábado, seu pai a levou pela primeira vez.','Ela viu palhaços, mágicos e um elefante enorme.','O número que mais gostou foi o do trapézio.','Bia voltou para casa dizendo que queria ser trapezista.'],perguntas:[{tipo:'multipla',enunciado:'Quando Bia foi ao circo?',opcoes:['No domingo','No sábado','Na segunda-feira'],correta:1,explicacao:'O texto diz "No sábado".'},{tipo:'multipla',enunciado:'Qual número ela mais gostou?',opcoes:['Palhaços','Mágicos','Trapézio'],correta:2,explicacao:'O texto diz que ela mais gostou do trapézio.'},{tipo:'inferencia',enunciado:'O que Bia quer ser quando crescer?',opcoes:['Palhaça','Trapezista','Mágica'],correta:1,explicacao:'Ela disse que queria ser trapezista.'}]},
{id:'historia-09',titulo:'A bola mágica',autor:'Domínio público',anoEscolar:2,habilidadesBNCC:['EF02LP26','EF15LP04'],nivel:1,emoji:'⚽',corFundo:'linear-gradient(135deg,#e0f5d0,#d0e8e0)',texto:['Téo ganhou uma bola de futebol do avô.','Ele achou que a bola era mágica porque nunca errava o gol.','Treinou todos os dias durante uma semana.','No jogo contra outra escola, Téo fez três gols.','O avô sorriu e disse: \"A magia é o seu treino.\"'],perguntas:[{tipo:'multipla',enunciado:'Quem deu a bola para Téo?',opcoes:['O pai','O avô','O amigo'],correta:1,explicacao:'O texto diz "ganhou do avô".'},{tipo:'multipla',enunciado:'Quantos gols Téo fez no jogo?',opcoes:['Um','Dois','Três'],correta:2,explicacao:'O texto diz que ele fez três gols.'},{tipo:'inferencia',enunciado:'Por que Téo acertava sempre?',opcoes:['Porque a bola era mágica de verdade','Porque ele treinava muito','Porque teve sorte'],correta:1,explicacao:'O avô disse que a magia era o treino.'}]},
{id:'historia-10',titulo:'O dinossauro amigável',autor:'Domínio público',anoEscolar:2,habilidadesBNCC:['EF02LP26','EF15LP04'],nivel:2,emoji:'🦕',corFundo:'linear-gradient(135deg,#d8f0d0,#e8f5d8)',texto:['Dino era um dinossauro grande, mas muito gentil.','Os outros dinossauros tinham medo dele por causa do tamanho.','Um dia, um filhote caiu em um buraco fundo.','Dino esticou o pescoço comprido e salvou o filhote.','Desde então, todos viram que ele era um grande amigo.'],perguntas:[{tipo:'multipla',enunciado:'Como era Dino?',opcoes:['Grande e gentil','Pequeno e bravo','Rápido e assustador'],correta:0,explicacao:'O texto diz "grande, mas muito gentil".'},{tipo:'multipla',enunciado:'Quem caiu no buraco?',opcoes:['Dino','Um filhote','Um amigo'],correta:1,explicacao:'Um filhote caiu no buraco.'},{tipo:'inferencia',enunciado:'Por que os outros tinham medo de Dino?',opcoes:['Porque ele era bravo','Porque era grande','Porque rugia alto'],correta:1,explicacao:'Eles tinham medo por causa do tamanho dele.'}]},
{id:'historia-11',titulo:'O coelho e a cenoura',autor:'Domínio público',anoEscolar:2,habilidadesBNCC:['EF02LP26','EF15LP03'],nivel:1,emoji:'🐰',corFundo:'linear-gradient(135deg,#fff0d0,#ffe0d0)',texto:['Beto era um coelho que adorava cenouras.','Ele plantou uma semente em sua horta.','Todos os dias, Beto regava a plantinha.','Depois de muitas semanas, uma cenoura enorme cresceu.','Beto ficou tão feliz que chamou os amigos para dividir.'],perguntas:[{tipo:'multipla',enunciado:'O que Beto plantou?',opcoes:['Uma flor','Uma cenoura','Uma árvore'],correta:1,explicacao:'O texto diz que ele plantou uma semente de cenoura.'},{tipo:'multipla',enunciado:'O que Beto fazia todos os dias?',opcoes:['Regava a plantinha','Colhia cenouras','Brincava no quintal'],correta:0,explicacao:'Ele regava a plantinha todos os dias.'},{tipo:'inferencia',enunciado:'O que Beto fez quando a cenoura cresceu?',opcoes:['Comeu sozinho','Chamou os amigos para dividir','Guardou para depois'],correta:1,explicacao:'Ele chamou os amigos para dividir.'}]},
{id:'historia-12',titulo:'A festa junina',autor:'Domínio público',anoEscolar:2,habilidadesBNCC:['EF02LP26','EF15LP03'],nivel:1,emoji:'🌽',corFundo:'linear-gradient(135deg,#fff0c0,#ffe8b0)',texto:['A escola de Nina preparou uma festa junina.','Nina dançou quadrilha com seus amigos.','Tinha bolo de milho, pipoca e quentão.','Também tinha uma barraca de pescaria.','Nina ganhou um peixinho de brinquedo e ficou muito feliz.'],perguntas:[{tipo:'multipla',enunciado:'Qual dança Nina dançou?',opcoes:['Samba','Quadrilha','Forró'],correta:1,explicacao:'O texto diz que ela dançou quadrilha.'},{tipo:'multipla',enunciado:'O que tinha de comer?',opcoes:['Pizza e refrigerante','Bolo de milho, pipoca e quentão','Só doces'],correta:1,explicacao:'O texto lista esses alimentos.'},{tipo:'multipla',enunciado:'O que Nina ganhou na pescaria?',opcoes:['Um peixe de verdade','Um peixinho de brinquedo','Um urso'],correta:1,explicacao:'Ela ganhou um peixinho de brinquedo.'}]},
{id:'historia-13',titulo:'O urso e o mel',autor:'Domínio público',anoEscolar:2,habilidadesBNCC:['EF02LP26','EF15LP04'],nivel:2,emoji:'🐻',corFundo:'linear-gradient(135deg,#f5e0c0,#e8d0a0)',texto:['Tavi era um urso que amava mel.','Ele viu uma colmeia em uma árvore alta.','Subiu com cuidado, mas as abelhas ficaram bravas.','Tavi caiu no chão e ficou com o nariz inchado.','Aprendeu que o mel deve ser comprado, não roubado.'],perguntas:[{tipo:'multipla',enunciado:'O que Tavi amava?',opcoes:['Frutas','Mel','Peixe'],correta:1,explicacao:'O texto diz que ele amava mel.'},{tipo:'multipla',enunciado:'Onde estava a colmeia?',opcoes:['No chão','Em uma árvore alta','Dentro de uma caverna'],correta:1,explicacao:'Ele viu a colmeia em uma árvore alta.'},{tipo:'inferencia',enunciado:'O que Tavi aprendeu?',opcoes:['A subir em árvores','Que não deve roubar mel','A fugir de abelhas'],correta:1,explicacao:'Ele aprendeu que o mel deve ser comprado, não roubado.'}]},
{id:'historia-14',titulo:'O trem colorido',autor:'Domínio público',anoEscolar:2,habilidadesBNCC:['EF02LP26','EF15LP03'],nivel:1,emoji:'🚂',corFundo:'linear-gradient(135deg,#d0e8f0,#e8f0f8)',texto:['Tico era um trem colorido que fazia a rota do campo à cidade.','Cada vagão tinha uma cor diferente: vermelho, azul e amarelo.','Passava por fazendas, rios e montanhas.','As crianças sempre acenavam quando o trem passava.','Tico apitava bem alto para responder, todo feliz.'],perguntas:[{tipo:'multipla',enunciado:'Quais cores tinha o trem?',opcoes:['Vermelho, azul e amarelo','Verde e preto','Rosa e roxo'],correta:0,explicacao:'O texto cita essas três cores.'},{tipo:'multipla',enunciado:'Por onde o trem passava?',opcoes:['Só na cidade','Por fazendas, rios e montanhas','Só no mar'],correta:1,explicacao:'O texto diz que ele passava por esses lugares.'},{tipo:'inferencia',enunciado:'Por que Tico apitava?',opcoes:['Porque estava com raiva','Para responder às crianças','Para avisar que estava com fome'],correta:1,explicacao:'Ele apitava para responder às crianças que acenavam.'}]},
{id:'historia-15',titulo:'A princesa e o sapo',autor:'Domínio público',anoEscolar:2,habilidadesBNCC:['EF02LP26','EF15LP04'],nivel:2,emoji:'🐸',corFundo:'linear-gradient(135deg,#e0f0d0,#d0e8f0)',texto:['Uma princesa chamada Clara brincava no jardim.','Ela viu um sapo falante que pediu ajuda.','Clara não teve medo e o ajudou a sair do poço.','O sapo virou um príncipe, mas Clara disse que o importante era a amizade.','Os dois brincaram juntos todos os dias no castelo.'],perguntas:[{tipo:'multipla',enunciado:'Onde Clara brincava?',opcoes:['No castelo','No jardim','Na escola'],correta:1,explicacao:'O texto diz que ela brincava no jardim.'},{tipo:'multipla',enunciado:'O que o sapo pediu?',opcoes:['Ajuda para sair do poço','Comida','Um abraço'],correta:0,explicacao:'O sapo pediu ajuda para sair do poço.'},{tipo:'inferencia',enunciado:'O que Clara disse ser mais importante?',opcoes:['O castelo','A amizade','A coroa'],correta:1,explicacao:'Ela disse que o importante era a amizade.'}]},
{id:'historia-16',titulo:'O dia na praia',autor:'Domínio público',anoEscolar:2,habilidadesBNCC:['EF02LP26','EF15LP03'],nivel:1,emoji:'🏖️',corFundo:'linear-gradient(135deg,#ffe8c0,#c0e8f0)',texto:['A família de Rui foi à praia no domingo.','Ele fez um castelo de areia com o pai.','A mãe trouxe sanduíche e suco para o almoço.','Rui viu um caranguejo pequeno perto da água.','Antes de ir embora, Rui tirou uma foto do castelo.'],perguntas:[{tipo:'multipla',enunciado:'Quando a família foi à praia?',opcoes:['No sábado','No domingo','Na sexta-feira'],correta:1,explicacao:'O texto diz "no domingo".'},{tipo:'multipla',enunciado:'O que Rui fez na praia?',opcoes:['Um castelo de areia','Uma bolha','Um bolo'],correta:0,explicacao:'Ele fez um castelo de areia com o pai.'},{tipo:'multipla',enunciado:'O que Rui viu perto da água?',opcoes:['Uma estrela-do-mar','Um caranguejo','Um peixe grande'],correta:1,explicacao:'Ele viu um caranguejo pequeno.'}]},
{id:'historia-17',titulo:'A abelha e a flor',autor:'Domínio público',anoEscolar:2,habilidadesBNCC:['EF02LP26','EF15LP04'],nivel:2,emoji:'🐝',corFundo:'linear-gradient(135deg,#fff5c0,#ffe0a0)',texto:['Bia era uma abelha que buscava néctar todos os dias.','Ela voou por um jardim cheio de flores coloridas.','Uma flor perguntou: \"Por que você leva o néctar?\"','Bia explicou que transforma o néctar em mel para toda a colmeia.','A flor ficou feliz por ajudar as abelhas.'],perguntas:[{tipo:'multipla',enunciado:'O que Bia buscava?',opcoes:['Água','Néctar','Folhas'],correta:1,explicacao:'O texto diz que ela buscava néctar.'},{tipo:'inferencia',enunciado:'Para que serve o néctar?',opcoes:['Para fazer mel','Para fazer pão','Para regar flores'],correta:0,explicacao:'Bia transforma o néctar em mel.'},{tipo:'multipla',enunciado:'Como a flor ficou no final?',opcoes:['Triste','Feliz por ajudar','Brava'],correta:1,explicacao:'A flor ficou feliz por ajudar as abelhas.'}]},
{id:'historia-18',titulo:'O lobo que não era mau',autor:'Domínio público',anoEscolar:2,habilidadesBNCC:['EF02LP26','EF15LP04'],nivel:2,emoji:'🐺',corFundo:'linear-gradient(135deg,#d0d8e8,#c0d0e0)',texto:['Lupo era um lobo que gostava de flores.','Os animais da floresta tinham medo só por ele ser lobo.','Um dia, um coelho ficou preso em um galho.','Lupo ajudou o coelho a se soltar com muito cuidado.','Os outros animais perceberam que Lupo era gentil.'],perguntas:[{tipo:'multipla',enunciado:'O que Lupo gostava?',opcoes:['De caçar','De flores','De correr'],correta:1,explicacao:'O texto diz que Lupo gostava de flores.'},{tipo:'inferencia',enunciado:'Por que os animais tinham medo de Lupo?',opcoes:['Porque ele era grande','Só por ele ser lobo','Porque ele rugia'],correta:1,explicacao:'Eles tinham medo só por ele ser lobo.'},{tipo:'multipla',enunciado:'Quem Lupo ajudou?',opcoes:['Um coelho','Uma raposa','Um pássaro'],correta:0,explicacao:'Ele ajudou um coelho preso em um galho.'}]},
{id:'historia-19',titulo:'A viagem de balão',autor:'Domínio público',anoEscolar:2,habilidadesBNCC:['EF02LP26','EF15LP04'],nivel:2,emoji:'🎈',corFundo:'linear-gradient(135deg,#e0e0ff,#f0e0ff)',texto:['Duda sonhava em voar em um balão.','No aniversário de 8 anos, ganhou um passeio de balão.','Lá de cima, viu casas pequenas e rios compridos.','Duda ficou com um pouco de medo, mas o piloto a tranquilizou.','Ao pousar, ela disse que foi o dia mais feliz da vida.'],perguntas:[{tipo:'multipla',enunciado:'O que Duda ganhou de aniversário?',opcoes:['Um brinquedo','Um passeio de balão','Um livro'],correta:1,explicacao:'Ela ganhou um passeio de balão.'},{tipo:'multipla',enunciado:'O que Duda viu lá de cima?',opcoes:['Casas pequenas e rios compridos','Nuvens só','Pássaros'],correta:0,explicacao:'Ela viu casas pequenas e rios compridos.'},{tipo:'inferencia',enunciado:'Como Duda se sentiu ao pousar?',opcoes:['Triste','Com muito medo','Muito feliz'],correta:2,explicacao:'Ela disse que foi o dia mais feliz da vida.'}]},
{id:'historia-20',titulo:'A galinha e o pintinho',autor:'Domínio público',anoEscolar:2,habilidadesBNCC:['EF02LP26','EF15LP03'],nivel:1,emoji:'🐔',corFundo:'linear-gradient(135deg,#fff0d0,#ffe0c0)',texto:['Dona Galinha tinha um pintinho chamado Piu.','Piu era muito curioso e sempre saía do galinheiro.','Um dia, ele se perdeu no quintal.','Dona Galinha chamou: \"Piu, Piu!\" e ele correu para ela.','Piu prometeu não se afastar mais sem a mãe.'],perguntas:[{tipo:'multipla',enunciado:'Como se chamava o pintinho?',opcoes:['Beto','Piu','Tico'],correta:1,explicacao:'O texto diz que o pintinho se chamava Piu.'},{tipo:'multipla',enunciado:'O que aconteceu com Piu?',opcoes:['Se perdeu no quintal','Foi embora','Dormiu'],correta:0,explicacao:'Ele se perdeu no quintal.'},{tipo:'inferencia',enunciado:'O que Piu prometeu?',opcoes:['Não comer','Não sair mais sem a mãe','Ficar no galinheiro para sempre'],correta:1,explicacao:'Ele prometeu não se afastar sem a mãe.'}]},
{id:'historia-21',titulo:'A tartaruga e a lebre',autor:'Domínio público',anoEscolar:2,habilidadesBNCC:['EF02LP26','EF15LP04'],nivel:2,emoji:'🐢',corFundo:'linear-gradient(135deg,#e0f0d0,#d0e8d0)',texto:['A lebre zombava da tartaruga por ela ser lenta.','A tartaruga desafiou a lebre para uma corrida.','A lebre correu rápido e, confiante, deitou para descansar.','A tartaruga continuou devagar, sem parar.','Quando a lebre acordou, a tartaruga já havia cruzado a linha.'],perguntas:[{tipo:'multipla',enunciado:'Quem desafiou quem para a corrida?',opcoes:['A lebre desafiou a tartaruga','A tartaruga desafiou a lebre','Ninguém desafiou'],correta:1,explicacao:'A tartaruga desafiou a lebre.'},{tipo:'multipla',enunciado:'O que a lebre fez durante a corrida?',opcoes:['Continuou correndo','Deitou para descansar','Desistiu'],correta:1,explicacao:'Ela deitou para descansar, confiante.'},{tipo:'inferencia',enunciado:'Qual é a lição da história?',opcoes:['Que correr é sempre melhor','Que devagar e sempre se chega lá','Que a lebre é mais forte'],correta:1,explicacao:'A tartaruga venceu por continuar devagar sem parar.'}]},
{id:'historia-22',titulo:'O menino e a pipa',autor:'Domínio público',anoEscolar:2,habilidadesBNCC:['EF02LP26','EF15LP03'],nivel:1,emoji:'🪁',corFundo:'linear-gradient(135deg,#d0e8ff,#c0e0f5)',texto:['Davi ganhou uma pipa do tio no fim de semana.','Ele foi ao parque com o pai para soltar a pipa.','O vento estava forte e a pipa subiu bem alto.','Davi segurava a linha com cuidado para não perder a pipa.','No fim da tarde, voltou para casa feliz e cansado.'],perguntas:[{tipo:'multipla',enunciado:'Quem deu a pipa para Davi?',opcoes:['O pai','O tio','O avô'],correta:1,explicacao:'O texto diz que ele ganhou do tio.'},{tipo:'multipla',enunciado:'Onde Davi soltou a pipa?',opcoes:['No quintal','No parque','Na escola'],correta:1,explicacao:'Ele foi ao parque com o pai.'},{tipo:'multipla',enunciado:'Como Davi voltou para casa?',opcoes:['Triste','Com raiva','Feliz e cansado'],correta:2,explicacao:'O texto diz que voltou feliz e cansado.'}]},
{id:'historia-23',titulo:'A festa na floresta',autor:'Domínio público',anoEscolar:2,habilidadesBNCC:['EF02LP26','EF15LP04'],nivel:2,emoji:'🦊',corFundo:'linear-gradient(135deg,#fff0c0,#ffe0a0)',texto:['Os animais da floresta decidiram fazer uma festa.','O macaco trouxe frutas e o coelho trouxe cenouras.','A coruja ficou responsável pela música.','Quando a noite chegou, todos dançaram ao redor da fogueira.','A raposa, que era tímida, no começo só olhava.','Mas o esquilo a convidou para dançar, e ela ficou feliz.'],perguntas:[{tipo:'multipla',enunciado:'O que o macaco trouxe?',opcoes:['Cenouras','Frutas','Música'],correta:1,explicacao:'O texto diz que o macaco trouxe frutas.'},{tipo:'multipla',enunciado:'Quem cuidou da música?',opcoes:['O coelho','A coruja','O esquilo'],correta:1,explicacao:'A coruja ficou responsável pela música.'},{tipo:'inferencia',enunciado:'Por que a raposa só olhava no começo?',opcoes:['Porque estava com sono','Porque era tímida','Porque não gostava de festa'],correta:1,explicacao:'O texto diz que ela era tímida.'}]},
{id:'historia-24',titulo:'O dia do livro',autor:'Domínio público',anoEscolar:2,habilidadesBNCC:['EF02LP26','EF15LP03'],nivel:1,emoji:'📖',corFundo:'linear-gradient(135deg,#e8e0ff,#d8d0f0)',texto:['Na escola de Sofia, houve uma feira do livro.','Cada aluno podia escolher um livro para levar para casa.','Sofia escolheu uma história sobre uma sereia.','Ela leu o livro em dois dias.','Depois, contou a história toda para a sua amiga.'],perguntas:[{tipo:'multipla',enunciado:'O que houve na escola de Sofia?',opcoes:['Uma festa','Uma feira do livro','Um passeio'],correta:1,explicacao:'O texto diz que houve uma feira do livro.'},{tipo:'multipla',enunciado:'Qual livro Sofia escolheu?',opcoes:['Sobre um dragão','Sobre uma sereia','Sobre um gato'],correta:1,explicacao:'Ela escolheu uma história sobre uma sereia.'},{tipo:'multipla',enunciado:'Em quanto tempo Sofia leu o livro?',opcoes:['Em uma semana','Em dois dias','Em um mês'],correta:1,explicacao:'Ela leu em dois dias.'}]},
{id:'historia-25',titulo:'A bicicleta nova',autor:'Domínio público',anoEscolar:2,habilidadesBNCC:['EF02LP26','EF15LP04'],nivel:2,emoji:'🚲',corFundo:'linear-gradient(135deg,#ffe0e8,#ffe8d0)',texto:['Caio ganhou uma bicicleta azul de aniversário.','No começo, ele caiu várias vezes tentando andar sem as rodinhas.','O pai o incentivou a não desistir.','Depois de uma semana treinando, Caio conseguiu pedalar sozinho.','Ele ficou tão feliz que saiu pedalando pela rua.'],perguntas:[{tipo:'multipla',enunciado:'Qual era a cor da bicicleta de Caio?',opcoes:['Vermelha','Verde','Azul'],correta:2,explicacao:'O texto diz que a bicicleta era azul.'},{tipo:'inferencia',enunciado:'Por que Caio caiu várias vezes?',opcoes:['Porque estava aprendendo','Porque a bicicleta era velha','Porque a rua era esburacada'],correta:0,explicacao:'Ele caiu porque estava aprendendo a andar sem as rodinhas.'},{tipo:'multipla',enunciado:'O que Caio fez quando conseguiu andar?',opcoes:['Guardou a bicicleta','Saiu pedalando pela rua','Deu a bicicleta para outra criança'],correta:1,explicacao:'Ele ficou tão feliz que saiu pedalando pela rua.'}]},
{id:'historia-26',titulo:'A vovó e o bolo',autor:'Domínio público',anoEscolar:2,habilidadesBNCC:['EF02LP26','EF15LP03'],nivel:1,emoji:'🎂',corFundo:'linear-gradient(135deg,#fff0d0,#ffe8e0)',texto:['Toda quinta-feira, a vovó de Nina fazia um bolo.','Nina adorava ajudar a misturar os ingredientes.','O bolo preferido era o de cenoura com cobertura de chocolate.','Enquanto o bolo assava, vovó e Nina brincavam de adivinhação.','Quando ficava pronto, o cheiro tomava a casa toda.'],perguntas:[{tipo:'multipla',enunciado:'Em que dia a vovó fazia bolo?',opcoes:['Na segunda-feira','Na quinta-feira','No sábado'],correta:1,explicacao:'O texto diz "toda quinta-feira".'},{tipo:'multipla',enunciado:'Qual era o bolo preferido?',opcoes:['Chocolate puro','Cenoura com cobertura de chocolate','Morango'],correta:1,explicacao:'O bolo preferido era de cenoura com cobertura de chocolate.'},{tipo:'multipla',enunciado:'O que vovó e Nina faziam enquanto o bolo assava?',opcoes:['Assistiam TV','Brincavam de adivinhação','Dormiam'],correta:1,explicacao:'O texto diz que brincavam de adivinhação.'}]},
{id:'historia-27',titulo:'O patinho diferente',autor:'Domínio público',anoEscolar:2,habilidadesBNCC:['EF02LP26','EF15LP04'],nivel:2,emoji:'🦢',corFundo:'linear-gradient(135deg,#e0f0ff,#d0e0f0)',texto:['Um patinho nasceu com penas brancas, diferente dos irmãos.','Os irmãos cinzas não queriam brincar com ele.','O patinho ficou triste e nadou sozinho pelo lago.','Um dia, ele viu seu reflexo na água e descobriu que era um cisne.','O cisne se juntou a outros cisnes e nunca mais ficou triste.'],perguntas:[{tipo:'multipla',enunciado:'Por que o patinho era diferente?',opcoes:['Porque tinha penas brancas','Porque era maior','Porque voava alto'],correta:0,explicacao:'Ele nasceu com penas brancas, diferente dos irmãos cinzas.'},{tipo:'inferencia',enunciado:'Por que o patinho ficou triste?',opcoes:['Porque não sabia voar','Porque os irmãos não queriam brincar com ele','Porque não gostava de água'],correta:1,explicacao:'Os irmãos cinzas não queriam brincar com ele.'},{tipo:'multipla',enunciado:'O que o patinho descobriu?',opcoes:['Que era um pato comum','Que era um cisne','Que era um ganso'],correta:1,explicacao:'Ele viu seu reflexo e descobriu que era um cisne.'}]},
{id:'historia-28',titulo:'A estrela cadente',autor:'Domínio público',anoEscolar:2,habilidadesBNCC:['EF02LP26','EF15LP04'],nivel:2,emoji:'🌠',corFundo:'linear-gradient(135deg,#d0d0f0,#c0c0e8)',texto:['Iara estava no quintal quando viu uma estrela cadente.','Ela fez um pedido em voz baixa, como a vovó tinha ensinado.','Pediu que sua família ficasse sempre unida.','No dia seguinte, seus primos que moravam longe chegaram de surpresa.','Iara sorriu, achando que o pedido tinha sido atendido.'],perguntas:[{tipo:'multipla',enunciado:'O que Iara viu no quintal?',opcoes:['Uma nuvem','Uma estrela cadente','Um pássaro'],correta:1,explicacao:'O texto diz que ela viu uma estrela cadente.'},{tipo:'inferencia',enunciado:'O que Iara pediu à estrela?',opcoes:['Um brinquedo novo','Que sua família ficasse sempre unida','Uma viagem'],correta:1,explicacao:'Ela pediu que sua família ficasse unida.'},{tipo:'multipla',enunciado:'O que aconteceu no dia seguinte?',opcoes:['Os primos chegaram de surpresa','Choveu','Ela ganhou um presente'],correta:0,explicacao:'Seus primos chegaram de surpresa.'}]},
{id:'historia-29',titulo:'A sementinha',autor:'Domínio público',anoEscolar:2,habilidadesBNCC:['EF02LP26','EF15LP03'],nivel:1,emoji:'🌱',corFundo:'linear-gradient(135deg,#e0f0d0,#d0e8c0)',texto:['Júlia plantou uma sementinha em um vaso.','Todos os dias, ela regava e olhava se tinha brotado.','Passaram-se muitos dias e nada acontecia.','Júlia quase desistiu, mas a mãe disse para esperar.','Um dia, um brotinho verde apareceu na terra.'],perguntas:[{tipo:'multipla',enunciado:'O que Júlia plantou?',opcoes:['Uma flor','Uma sementinha','Uma árvore'],correta:1,explicacao:'O texto diz que ela plantou uma sementinha.'},{tipo:'multipla',enunciado:'O que Júlia fazia todos os dias?',opcoes:['Regava e olhava','Colhia','Arrancava'],correta:0,explicacao:'Ela regava e olhava se tinha brotado.'},{tipo:'inferencia',enunciado:'O que a história ensina?',opcoes:['Que devemos desistir','Que é preciso ter paciência','Que regar não importa'],correta:1,explicacao:'A mãe disse para esperar, e o broto apareceu com paciência.'}]},
{id:'historia-30',titulo:'O amigo invisível',autor:'Domínio público',anoEscolar:2,habilidadesBNCC:['EF02LP26','EF15LP04'],nivel:2,emoji:'👻',corFundo:'linear-gradient(135deg,#e8e8ff,#e0e0f8)',texto:['Beto tinha um amigo invisível chamado Téo.','Brincavam juntos todos os dias no quintal.','Os pais de Beto achavam aquilo só imaginação.','Um dia, Beto caiu e se machucou, e Téo \"o ajudou\" a levantar.','Beto disse à mãe que Téo sempre cuidava dele.'],perguntas:[{tipo:'multipla',enunciado:'Como se chamava o amigo invisível de Beto?',opcoes:['Beto','Téo','Davi'],correta:1,explicacao:'O texto diz que o amigo se chamava Téo.'},{tipo:'multipla',enunciado:'O que os pais de Beto achavam?',opcoes:['Que Téo existia','Que era só imaginação','Que era um vizinho'],correta:1,explicacao:'Os pais achavam que era só imaginação.'},{tipo:'inferencia',enunciado:'O que Beto disse à mãe?',opcoes:['Que Téo sempre cuidava dele','Que não precisava mais de Téo','Que Téo tinha ido embora'],correta:0,explicacao:'Ele disse que Téo sempre cuidava dele.'}]},
{id:'historia-31',titulo:'O cachorro Pipoca',autor:'Domínio público',anoEscolar:2,habilidadesBNCC:['EF02LP26','EF15LP03'],nivel:1,emoji:'🐶',corFundo:'linear-gradient(135deg,#fff3d6,#ffe5b4)',texto:['Pipoca era um cachorro muito brincalhão.','Todo dia ele corria atrás da bola no jardim.','Um dia, a bola caiu num buraco pequeno.','Pipoca latiu e chamou a menina Ana.','Ana pegou a bola e deu um abraço em Pipoca.'],perguntas:[{tipo:'multipla',enunciado:'Quem era Pipoca?',opcoes:['Um gato','Um cachorro','Um coelho'],correta:1,explicacao:'O texto diz que Pipoca era um cachorro.'},{tipo:'multipla',enunciado:'Onde a bola caiu?',opcoes:['Num buraco pequeno','No rio','Na casa'],correta:0,explicacao:'A bola caiu num buraco pequeno.'},{tipo:'inferencia',enunciado:'Por que Pipoca latiu e chamou Ana?',opcoes:['Queria dormir','Precisava de ajuda para pegar a bola','Estava com fome'],correta:1,explicacao:'Ele não conseguia pegar a bola, então pediu ajuda.'}]},
{id:'historia-32',titulo:'O leão e o ratinho',autor:'Domínio público',anoEscolar:2,habilidadesBNCC:['EF02LP26','EF15LP04'],nivel:2,emoji:'🦁',corFundo:'linear-gradient(135deg,#ffe8c2,#ffd9a0)',texto:['Um leão dormia debaixo de uma árvore grande.','Um ratinho passou correndo e acordou o leão.','O leão ficou bravo, mas o ratinho pediu desculpas.','O leão sorriu e deixou o ratinho ir embora.','Dias depois, o leão ficou preso numa rede.','O ratinho roeu as cordas e salvou o leão.'],perguntas:[{tipo:'multipla',enunciado:'Onde o leão dormia?',opcoes:['Dentro de uma toca','Debaixo de uma árvore','Na beira do rio'],correta:1,explicacao:'O leão dormia debaixo de uma árvore grande.'},{tipo:'multipla',enunciado:'O que o ratinho roeu?',opcoes:['As cordas da rede','Um pedaço de pão','Uma folha'],correta:0,explicacao:'Ele roeu as cordas e salvou o leão.'},{tipo:'inferencia',enunciado:'Por que o ratinho ajudou o leão?',opcoes:['Porque o leão tinha sido bom com ele','Porque tinha medo do leão','Porque queria a rede'],correta:0,explicacao:'O leão tinha deixado o ratinho ir embora, e o ratinho quis retribuir.'}]},
{id:'historia-33',titulo:'O arco-íris',autor:'Domínio público',anoEscolar:2,habilidadesBNCC:['EF02LP26','EF15LP03'],nivel:1,emoji:'🌈',corFundo:'linear-gradient(135deg,#e0f4ff,#fde2f3)',texto:['Choveu forte de manhã na casa de Lia.','Depois, a chuva parou e o sol apareceu.','Lia olhou pela janela e viu algo bonito no céu.','Era um arco-íris cheio de cores.','Ela chamou o irmão para ver também.'],perguntas:[{tipo:'multipla',enunciado:'Quando choveu forte?',opcoes:['De manhã','De noite','De tarde'],correta:0,explicacao:'O texto diz que choveu forte de manhã.'},{tipo:'multipla',enunciado:'O que Lia viu no céu?',opcoes:['Uma estrela','Um balão','Um arco-íris'],correta:2,explicacao:'Lia viu um arco-íris cheio de cores.'},{tipo:'inferencia',enunciado:'Por que Lia chamou o irmão?',opcoes:['Queria que ele visse o arco-íris','Queria brincar na chuva','Estava com medo'],correta:0,explicacao:'Ela achou bonito e quis dividir com o irmão.'}]},
{id:'historia-34',titulo:'O aquário da escola',autor:'Domínio público',anoEscolar:2,habilidadesBNCC:['EF02LP26','EF15LP03'],nivel:1,emoji:'🐠',corFundo:'linear-gradient(135deg,#d6f1ff,#c2e6ff)',texto:['Na sala de aula havia um aquário pequeno.','Nele moravam três peixinhos laranja.','Todo dia, um aluno dava comida aos peixes.','Hoje era a vez de Caio.','Ele colocou só um pouquinho, do jeito que a professora ensinou.'],perguntas:[{tipo:'multipla',enunciado:'Quantos peixinhos moravam no aquário?',opcoes:['Dois','Três','Cinco'],correta:1,explicacao:'O texto diz que eram três peixinhos laranja.'},{tipo:'multipla',enunciado:'Quem deu comida aos peixes hoje?',opcoes:['Caio','A professora','Lia'],correta:0,explicacao:'Hoje era a vez de Caio.'},{tipo:'inferencia',enunciado:'Por que Caio colocou só um pouquinho de comida?',opcoes:['Porque estava com preguiça','Porque a professora ensinou assim','Porque a comida acabou'],correta:1,explicacao:'Ele fez do jeito que a professora ensinou.'}]},
{id:'historia-35',titulo:'A maçã dividida',autor:'Domínio público',anoEscolar:2,habilidadesBNCC:['EF02LP26','EF15LP04'],nivel:2,emoji:'🍎',corFundo:'linear-gradient(135deg,#ffe0e0,#ffd0d0)',texto:['Teo ganhou uma maçã vermelha e grande.','No recreio, ele viu Duda sem lanche.','Teo pensou um pouco e cortou a maçã ao meio.','Deu uma metade para Duda.','Os dois comeram juntos e sorriram.'],perguntas:[{tipo:'multipla',enunciado:'De que cor era a maçã?',opcoes:['Verde','Amarela','Vermelha'],correta:2,explicacao:'O texto diz que a maçã era vermelha e grande.'},{tipo:'multipla',enunciado:'Com quem Teo dividiu a maçã?',opcoes:['Com Duda','Com a professora','Com o irmão'],correta:0,explicacao:'Ele deu uma metade para Duda.'},{tipo:'inferencia',enunciado:'Por que Teo dividiu a maçã?',opcoes:['Porque não gostava de maçã','Porque Duda estava sem lanche','Porque a maçã era pequena'],correta:1,explicacao:'Ele viu Duda sem lanche e quis ajudar.'}]},
{id:'historia-36',titulo:'O elefante e o passarinho',autor:'Domínio público',anoEscolar:2,habilidadesBNCC:['EF02LP26','EF15LP04'],nivel:2,emoji:'🐘',corFundo:'linear-gradient(135deg,#e8eaf6,#d8dcf0)',texto:['Um elefante grande andava pela mata.','Um passarinho fez o ninho na árvore dele.','O elefante não queria balançar a árvore.','Por isso, ele ficou parado por muitos dias.','Quando os filhotes nasceram, o elefante sorriu feliz.'],perguntas:[{tipo:'multipla',enunciado:'Onde o passarinho fez o ninho?',opcoes:['Numa árvore','Numa pedra','Numa casa'],correta:0,explicacao:'O ninho foi feito na árvore.'},{tipo:'multipla',enunciado:'Quanto tempo o elefante ficou parado?',opcoes:['Uma hora','Muitos dias','Uma noite'],correta:1,explicacao:'O texto diz que ele ficou parado por muitos dias.'},{tipo:'inferencia',enunciado:'O que o elefante sentiu pelo passarinho?',opcoes:['Cuidado e carinho','Raiva','Medo'],correta:0,explicacao:'Ele ficou parado para não derrubar o ninho, por cuidado.'}]},
{id:'historia-37',titulo:'O primeiro dia de aula',autor:'Domínio público',anoEscolar:2,habilidadesBNCC:['EF02LP26','EF15LP03'],nivel:1,emoji:'🎒',corFundo:'linear-gradient(135deg,#e6f7d9,#d4f0c0)',texto:['Hoje foi o primeiro dia de aula de Rui.','Ele arrumou a mochila e vestiu o uniforme.','No portão, a professora Sara esperava a turma.','Rui ficou um pouco tímido no início.','Depois, fez um amigo novo e brincou muito.'],perguntas:[{tipo:'multipla',enunciado:'Como se chamava a professora?',opcoes:['Ana','Sara','Lia'],correta:1,explicacao:'A professora se chamava Sara.'},{tipo:'multipla',enunciado:'O que Rui fez depois de ficar tímido?',opcoes:['Foi embora','Chorou','Fez um amigo novo'],correta:2,explicacao:'Depois, ele fez um amigo novo e brincou muito.'},{tipo:'inferencia',enunciado:'Como Rui se sentiu no final do dia?',opcoes:['Alegre','Zangado','Cansado de brincar'],correta:0,explicacao:'Ele fez um amigo e brincou muito, então ficou alegre.'}]},
{id:'historia-38',titulo:'A borboleta',autor:'Domínio público',anoEscolar:2,habilidadesBNCC:['EF02LP26','EF15LP04'],nivel:2,emoji:'🦋',corFundo:'linear-gradient(135deg,#f3e5ff,#e6d4ff)',texto:['Primeiro, a borboleta era uma lagarta verde.','Ela comia folhas o dia inteiro.','Depois, se escondeu num casulo e ficou quietinha.','Passaram-se os dias, e o casulo se abriu.','De dentro saiu uma linda borboleta colorida.'],perguntas:[{tipo:'multipla',enunciado:'Como era a lagarta no começo?',opcoes:['Azul','Verde','Amarela'],correta:1,explicacao:'No começo, ela era uma lagarta verde.'},{tipo:'multipla',enunciado:'O que a lagarta comia?',opcoes:['Folhas','Flores','Frutas'],correta:0,explicacao:'Ela comia folhas o dia inteiro.'},{tipo:'inferencia',enunciado:'O que aconteceu dentro do casulo?',opcoes:['A lagarta foi embora','A lagarta virou borboleta','A lagarta ficou pequena'],correta:1,explicacao:'Com o tempo, a lagarta se transformou numa borboleta.'}]},
{id:'historia-39',titulo:'A lua e o menino',autor:'Domínio público',anoEscolar:2,habilidadesBNCC:['EF02LP26','EF15LP03'],nivel:1,emoji:'🌙',corFundo:'linear-gradient(135deg,#e3e8ff,#cfd8ff)',texto:['À noite, Davi não conseguia dormir.','Ele olhou pela janela e viu a lua grande.','A lua brilhava e iluminava o quintal.','Davi ficou olhando e sentiu calma.','Logo ele fechou os olhos e dormiu.'],perguntas:[{tipo:'multipla',enunciado:'O que Davi viu pela janela?',opcoes:['O sol','A lua','Um avião'],correta:1,explicacao:'Ele viu a lua grande.'},{tipo:'multipla',enunciado:'O que a lua iluminava?',opcoes:['O quintal','A escola','A rua toda'],correta:0,explicacao:'A lua iluminava o quintal.'},{tipo:'inferencia',enunciado:'Por que Davi conseguiu dormir?',opcoes:['Porque ficou calmo olhando a lua','Porque a mãe cantou','Porque amanheceu'],correta:0,explicacao:'Olhar a lua trouxe calma, e ele dormiu.'}]},
{id:'historia-40',titulo:'A joaninha perdida',autor:'Domínio público',anoEscolar:2,habilidadesBNCC:['EF02LP26','EF15LP04'],nivel:2,emoji:'🐞',corFundo:'linear-gradient(135deg,#ffe5e5,#ffd6d6)',texto:['Uma joaninha vermelha se perdeu no jardim.','Ela não achava mais o caminho de casa.','Uma formiguinha viu a joaninha triste.','A formiga a levou até a folha onde ela morava.','A joaninha agradeceu e as duas viraram amigas.'],perguntas:[{tipo:'multipla',enunciado:'De que cor era a joaninha?',opcoes:['Vermelha','Azul','Preta'],correta:0,explicacao:'O texto diz que a joaninha era vermelha.'},{tipo:'multipla',enunciado:'Quem ajudou a joaninha?',opcoes:['Uma abelha','Uma formiguinha','Uma borboleta'],correta:1,explicacao:'Uma formiguinha viu a joaninha e a levou para casa.'},{tipo:'inferencia',enunciado:'Como a joaninha se sentia antes de ser ajudada?',opcoes:['Feliz','Com sono','Triste e perdida'],correta:2,explicacao:'A formiguinha a viu triste porque ela estava perdida.'}]},
{id:'historia-41',titulo:'A tarde na feira e o caderno de anotações',autor:'Domínio público',anoEscolar:2,habilidadesBNCC:['EF02LP26','EF15LP03'],nivel:2,emoji:'🧺',corFundo:'linear-gradient(135deg,#ffe8cc,#e0f0d0)',texto:['No sábado de manhã, Lucas acordou cedo para ajudar a avó na feira do bairro.','O sol ainda estava fraco quando eles chegaram e arrumaram as frutas e verduras nas bancas.','Lucas gostava de observar o movimento: vizinhos conversando, crianças escolhendo mangas e o cheiro de cheiro-verde fresco no ar.','No meio da manhã, a avó pediu que ele fizesse uma lista do que estava acabando.','Lucas pegou seu caderno pequeno e anotou tudo com calma, separando o que precisava repor no mesmo dia do que podia esperar até a próxima semana.','Quando uma cliente perguntou o preço de duas dúzias de bananas, ele fez a conta de cabeça, conferiu na tabela e entregou o troco certo, ganhando um sorriso de agradecimento da avó.'],perguntas:[{tipo:'multipla',enunciado:'Quem Lucas foi ajudar na feira?',opcoes:['A avó','O pai','O vizinho'],correta:0,explicacao:'O texto diz que Lucas acordou cedo para ajudar a avó na feira.'},{tipo:'multipla',enunciado:'O que a avó pediu que Lucas fizesse no meio da manhã?',opcoes:['Arrumar as bananas','Uma lista do que estava acabando','Um desenho da feira'],correta:1,explicacao:'A avó pediu que ele fizesse uma lista do que estava acabando.'},{tipo:'inferencia',enunciado:'Por que a avó sorriu para Lucas no final?',opcoes:['Porque ele fez a conta e entregou o troco certo','Porque ele chegou tarde','Porque ele comeu uma manga'],correta:0,explicacao:'Ele ajudou a cliente e entregou o troco certo, por isso ganhou um sorriso de agradecimento.'}]},
{id:'historia-42',titulo:'O pão quentinho da manhã',autor:'Domínio público',anoEscolar:3,habilidadesBNCC:['EF02LP26','EF15LP04'],nivel:3,emoji:'🥖',corFundo:'linear-gradient(135deg,#dbeafe,#e0f0ff)',texto:['Todo dia antes de a escola abrir, Seu Antônio acende o forno da padaria da esquina.','O cheiro de pão assando se espalha pela rua e faz muita gente apressar o passo para buscar o café da manhã.','Rafael costumava passar lá com o pai e ajudava a contar os pãezinhos que saíam da assadeira.','Certo dia, percebeu que um pacote havia ficado rasgado na ponta e avisou Seu Antônio antes que alguém levasse.','O padeiro agradeceu com um sorriso e separou o pacote para o lanche da equipe.','Rafael saiu contente, sentindo que tinha ajudado a evitar desperdício.'],perguntas:[{tipo:'multipla',enunciado:'O que Rafael percebeu de errado na padaria?',opcoes:['Que um pacote de pão estava rasgado na ponta.','Que o forno estava apagado.','Que a padaria tinha fechado mais cedo.'],correta:0,explicacao:'Rafael notou o pacote rasgado e avisou Seu Antônio para evitar desperdício.'},{tipo:'multipla',enunciado:'Quem acende o forno da padaria todo dia?',opcoes:['Rafael','Seu Antônio','O pai de Rafael'],correta:1,explicacao:'O texto diz que Seu Antônio acende o forno.'},{tipo:'inferencia',enunciado:'Por que Rafael saiu contente da padaria?',opcoes:['Porque ganhou todos os pães','Porque sentiu que ajudou a evitar desperdício','Porque a escola foi cancelada'],correta:1,explicacao:'Ele avisou do pacote rasgado e sentiu que ajudou a evitar desperdício.'}]},
{id:'historia-43',titulo:'A planta que precisava de sol',autor:'Domínio público',anoEscolar:3,habilidadesBNCC:['EF02LP26','EF15LP04'],nivel:3,emoji:'🌿',corFundo:'linear-gradient(135deg,#fde2f3,#ffe0e0)',texto:['Tia Lúcia tinha um vaso de manjericão em cima da mesa da cozinha, perto de uma janela pequena.','Com o passar das semanas, as folhas ficaram mais claras e os ramos começaram a pender para o lado.','Bia observou a planta e lembrou da aula de Ciências sobre luz e crescimento.','Ela sugeriu colocar o vaso na varanda durante a manhã, onde batia o sol suave das primeiras horas.','Depois de alguns dias recebendo luz e água na medida certa, o manjericão recuperou a cor verde-escura e o perfume ficou ainda mais forte.','Tia Lúcia elogiou a atenção da sobrinha.'],perguntas:[{tipo:'multipla',enunciado:'Por que as folhas do manjericão estavam ficando mais claras?',opcoes:['Porque estavam recebendo pouca luz do sol na mesa da cozinha.','Porque estavam dentro da geladeira.','Porque tinham sido cortadas com tesoura.'],correta:0,explicacao:'O texto mostra que a planta melhorou ao receber o sol da manhã na varanda.'},{tipo:'multipla',enunciado:'Onde Bia sugeriu colocar o vaso?',opcoes:['Na varanda, durante a manhã','Dentro do armário','Embaixo da pia'],correta:0,explicacao:'Ela sugeriu a varanda, onde batia o sol suave das primeiras horas.'},{tipo:'inferencia',enunciado:'O que mostra que o manjericão ficou saudável de novo?',opcoes:['As folhas caíram todas','Ele recuperou a cor verde-escura e o perfume ficou mais forte','Ele ficou menor'],correta:1,explicacao:'A cor e o perfume voltaram, sinal de que a planta melhorou.'}]},
{id:'historia-44',titulo:'O jogo de dominó na varanda',autor:'Domínio público',anoEscolar:3,habilidadesBNCC:['EF02LP26','EF15LP04'],nivel:3,emoji:'🎲',corFundo:'linear-gradient(135deg,#ffe8cc,#fff3d6)',texto:['No domingo à tarde, o calor diminuiu e o avô de Tiago puxou uma mesinha de madeira para a varanda.','Ele tirou da caixa uma caixinha antiga de dominó e chamou o neto para uma partida.','No começo, Tiago jogava sem pensar muito e acabava ficando sem peças que encaixavam nas pontas.','O avô pediu que ele olhasse com calma os números que já estavam na mesa antes de escolher.','Na segunda rodada, Tiago contou os pontos com atenção e planejou suas jogadas.','Mesmo quando perdeu por uma peça, riu junto com o avô e combinou outra partida para a semana seguinte.'],perguntas:[{tipo:'multipla',enunciado:'O que ajudou Tiago a jogar melhor na segunda rodada?',opcoes:['Observar os números na mesa e planejar as jogadas com calma.','Esconder as peças do avô.','Jogar sem olhar as próprias peças.'],correta:0,explicacao:'O avô orientou Tiago a olhar os números na mesa antes de jogar, e ele planejou melhor.'},{tipo:'multipla',enunciado:'Com quem Tiago jogou dominó?',opcoes:['Com o pai','Com o avô','Com a professora'],correta:1,explicacao:'O avô de Tiago o chamou para a partida.'},{tipo:'inferencia',enunciado:'Como Tiago reagiu ao perder por uma peça?',opcoes:['Ficou bravo e foi embora','Riu com o avô e combinou outra partida','Escondeu o jogo'],correta:1,explicacao:'Ele riu junto com o avô e combinou outra partida.'}]},
{id:'historia-45',titulo:'A bicicleta com o pneu murcho',autor:'Domínio público',anoEscolar:3,habilidadesBNCC:['EF02LP26','EF15LP04'],nivel:3,emoji:'🚲',corFundo:'linear-gradient(135deg,#e0f0d0,#d6f5e3)',texto:['Mateus ia pedalar com os amigos no fim da tarde, mas, ao tirar a bicicleta da garagem, percebeu que o pneu de trás estava bem murcho.','Se saísse daquele jeito, o passeio ia ficar difícil e podia até estragar a câmara de ar.','Ele pegou a bomba de ar encostada na parede e começou a encher o pneu devagar, conferindo com a mão se estava ficando firme sem ficar duro demais.','Quando o pneu ficou no ponto certo, Mateus testou o freio e saiu para encontrar a turma.','Chegou na hora combinada e aproveitou a tarde inteira sem nenhum aperto.'],perguntas:[{tipo:'multipla',enunciado:'O que Mateus fez antes de sair para pedalar com os amigos?',opcoes:['Encheu o pneu traseiro com a bomba de ar e testou o freio.','Deixou a bicicleta no quintal e foi a pé.','Tirou as duas rodas da bicicleta.'],correta:0,explicacao:'Ele encheu o pneu murcho com a bomba de ar e conferiu o freio antes de sair.'},{tipo:'multipla',enunciado:'Qual pneu estava murcho?',opcoes:['O da frente','O de trás','Os dois'],correta:1,explicacao:'O texto diz que o pneu de trás estava bem murcho.'},{tipo:'inferencia',enunciado:'Por que Mateus conferiu o pneu com a mão?',opcoes:['Para saber se estava firme, sem ficar duro demais','Para deixá-lo murcho','Porque estava com frio'],correta:0,explicacao:'Ele queria o pneu firme, mas não duro demais.'}]},
{id:'historia-46',titulo:'A receita de bolo da família',autor:'Domínio público',anoEscolar:3,habilidadesBNCC:['EF02LP26','EF15LP04'],nivel:3,emoji:'🎂',corFundo:'linear-gradient(135deg,#dbeafe,#e0f0ff)',texto:['No sábado, Helena e a mãe resolveram preparar um bolo simples para o lanche da tarde.','Elas separaram os ingredientes sobre a bancada e leram a receita juntas, passo a passo, para não esquecer nada.','Helena ficou responsável por medir o açúcar e a farinha com o copo medidor, enquanto a mãe misturava tudo com cuidado.','As duas conversavam e contavam histórias da infância enquanto o forno esquentava.','Quando o bolo ficou dourado e cresceu bonito, a casa inteira ficou com cheiro doce.','Elas esperaram esfriar um pouco para cortar as fatias e servir com suco natural.'],perguntas:[{tipo:'multipla',enunciado:'Qual foi a tarefa de Helena durante o preparo do bolo?',opcoes:['Medir o açúcar e a farinha com o copo medidor.','Acender o forno sozinha e cortar o bolo quente.','Lavar toda a louça antes de começar.'],correta:0,explicacao:'O segundo parágrafo informa que Helena mediu o açúcar e a farinha.'},{tipo:'multipla',enunciado:'Por que elas leram a receita juntas?',opcoes:['Para não esquecer nada','Para fazer o bolo mais rápido','Porque a receita estava escondida'],correta:0,explicacao:'Leram passo a passo para não esquecer nada.'},{tipo:'inferencia',enunciado:'Por que elas esperaram o bolo esfriar um pouco?',opcoes:['Porque o bolo estava azedo','Para cortar as fatias sem se queimar','Porque o suco acabou'],correta:1,explicacao:'Esperar esfriar deixa cortar e servir com segurança.'}]},
{id:'historia-47',titulo:'O caderno perdido no caminho',autor:'Domínio público',anoEscolar:3,habilidadesBNCC:['EF02LP26','EF15LP04'],nivel:3,emoji:'📓',corFundo:'linear-gradient(135deg,#fde2f3,#ffe0e0)',texto:['Na volta da escola, Gabriel parou para conversar com dois colegas perto da praça e deixou o caderno de atividades apoiado no banco.','Quando chegou em casa, sentiu falta dele ao arrumar a mochila para o dia seguinte.','Ele lembrou exatamente onde tinha parado e voltou depressa com o irmão mais novo.','O banco ainda estava lá, mas o caderno não estava mais sobre a madeira.','Os dois olharam em volta e viram o caderno perto de um canteiro, onde uma senhora o havia recolhido para não molhar.','A senhora entregou o caderno a Gabriel, que agradeceu bastante e prometeu ter mais atenção.'],perguntas:[{tipo:'multipla',enunciado:'Onde o caderno de Gabriel foi encontrado?',opcoes:['Perto de um canteiro, recolhido por uma senhora para não molhar.','Dentro da mochila do irmão.','Em cima da geladeira de casa.'],correta:0,explicacao:'Uma senhora havia recolhido o caderno perto de um canteiro para protegê-lo.'},{tipo:'multipla',enunciado:'Quando Gabriel sentiu falta do caderno?',opcoes:['Na escola','Ao arrumar a mochila em casa','Na praça'],correta:1,explicacao:'Ele sentiu falta ao arrumar a mochila para o dia seguinte.'},{tipo:'inferencia',enunciado:'O que Gabriel aprendeu com o que aconteceu?',opcoes:['A ter mais atenção com suas coisas','A nunca mais ir à praça','A não usar caderno'],correta:0,explicacao:'Ele prometeu ter mais atenção.'}]},
{id:'historia-48',titulo:'A sombra das árvores no recreio',autor:'Domínio público',anoEscolar:3,habilidadesBNCC:['EF02LP26','EF15LP04'],nivel:3,emoji:'🌳',corFundo:'linear-gradient(135deg,#ffe8cc,#fff3d6)',texto:['Durante o recreio, o sol forte deixava o pátio bem quente, e os alunos procuravam os cantos mais frescos para descansar.','Um grupo formou uma roda embaixo das mangueiras, onde a sombra deixava o ar mais agradável.','Em vez de correr debaixo do sol quente, eles inventaram um jogo de adivinhação com charadas e rimas.','Todo mundo participava, esperando a sua vez de falar sem tumulto.','Quando o sinal tocou avisando o fim do intervalo, todos levantaram calmos e organizados.','A roda embaixo da árvore tinha virado o ponto de encontro favorito da turma.'],perguntas:[{tipo:'multipla',enunciado:'Como o grupo aproveitou a sombra das mangueiras no recreio?',opcoes:['Fez uma roda e brincou de adivinhação com charadas e rimas.','Jogou bola no meio do sol quente.','Dormiu até o fim da aula.'],correta:0,explicacao:'O texto mostra que eles formaram uma roda na sombra e jogaram adivinhações.'},{tipo:'multipla',enunciado:'Por que os alunos procuravam cantos frescos?',opcoes:['Porque o sol forte deixava o pátio quente','Porque estava chovendo','Porque o pátio estava fechado'],correta:0,explicacao:'O sol forte deixava o pátio bem quente.'},{tipo:'inferencia',enunciado:'O que mostra que a brincadeira foi organizada?',opcoes:['Todos esperavam a sua vez de falar','Todos gritavam ao mesmo tempo','Ninguém participou'],correta:0,explicacao:'Esperar a vez de falar mostra organização.'}]},
{id:'historia-49',titulo:'A caixa de ferramentas do vizinho',autor:'Domínio público',anoEscolar:3,habilidadesBNCC:['EF02LP26','EF15LP04'],nivel:3,emoji:'🔧',corFundo:'linear-gradient(135deg,#e0f0d0,#d6f5e3)',texto:['Seu Jorge, vizinho da casa ao lado, estava consertando a dobradiça de um portão que fazia barulho toda vez que abria.','Caíam algumas gotas de chuva fina, e ele precisava terminar o serviço antes de escurecer.','Cauã viu que o vizinho procurava uma chave de fenda e foi até a própria casa buscar a que o pai guardava na gaveta.','Entregou a ferramenta na mão de Seu Jorge com cuidado.','Com o parafuso bem apertado, o portão parou de ranger e abriu macio.','Seu Jorge agradeceu a ajuda rápida de Cauã e mostrou como o ajuste tinha dado certo.'],perguntas:[{tipo:'multipla',enunciado:'Qual problema o portão de Seu Jorge apresentava?',opcoes:['Fazia barulho ao abrir por causa da dobradiça.','Estava pintado de azul.','Não tinha fechadura.'],correta:0,explicacao:'O primeiro parágrafo diz que o portão fazia barulho toda vez que abria.'},{tipo:'multipla',enunciado:'O que Cauã buscou para ajudar?',opcoes:['Uma chave de fenda','Um guarda-chuva','Uma escada'],correta:0,explicacao:'Ele buscou a chave de fenda que o pai guardava na gaveta.'},{tipo:'inferencia',enunciado:'Por que Seu Jorge agradeceu a Cauã?',opcoes:['Porque a ajuda rápida o ajudou a terminar o conserto','Porque Cauã pintou o portão','Porque Cauã levou a chuva embora'],correta:0,explicacao:'Com a ferramenta, o conserto foi concluído e o portão parou de ranger.'}]},
{id:'historia-50',titulo:'O cartaz da feira de ciências',autor:'Domínio público',anoEscolar:3,habilidadesBNCC:['EF02LP26','EF15LP04'],nivel:3,emoji:'🔬',corFundo:'linear-gradient(135deg,#dbeafe,#e0f0ff)',texto:['A turma do 5º ano estava preparando um cartaz para explicar como economizar água em casa e na escola.','Cada dupla ficou com uma parte: uns desenhavam, outros escreviam frases curtas e legíveis.','Luana e Davi ficaram responsáveis por revisar o texto antes de colar na cartolina.','Eles perceberam que duas palavras estavam repetidas e corrigiram com calma para o cartaz ficar claro.','No dia da apresentação, vários visitantes pararam para ler o trabalho e elogiaram os exemplos simples.','Luana e Davi explicaram cada dica com segurança.'],perguntas:[{tipo:'multipla',enunciado:'O que Luana e Davi fizeram antes de colar o texto na cartolina?',opcoes:['Revisaram o texto e corrigiram palavras repetidas.','Rasgaram o cartaz e desistiram.','Pintaram o chão da sala com tinta guache.'],correta:0,explicacao:'Eles revisaram o texto e tiraram palavras repetidas para deixá-lo claro.'},{tipo:'multipla',enunciado:'Qual era o assunto do cartaz?',opcoes:['Como economizar água','Como plantar feijão','Como fazer pipa'],correta:0,explicacao:'O cartaz explicava como economizar água em casa e na escola.'},{tipo:'inferencia',enunciado:'O que mostra que o trabalho agradou?',opcoes:['Os visitantes pararam para ler e elogiaram','Ninguém foi ver','O cartaz foi rasgado'],correta:0,explicacao:'Vários visitantes leram e elogiaram os exemplos.'}]},
{id:'historia-51',titulo:'A tarde sem energia elétrica',autor:'Domínio público',anoEscolar:3,habilidadesBNCC:['EF02LP26','EF15LP04'],nivel:3,emoji:'🕯️',corFundo:'linear-gradient(135deg,#fde2f3,#ffe0e0)',texto:['No meio da tarde, uma ventania derrubou um galho sobre a fiação e a energia elétrica acabou na rua.','A televisão e o ventilador desligaram na mesma hora, deixando a casa silenciosa.','Em vez de ficar reclamando, Sofia abriu as janelas para deixar o vento entrar e pegou dois livros de histórias.','Chamou a irmã mais nova para lerem juntas enquanto havia claridade.','Quando a luz voltou no fim da tarde, as duas já tinham terminado uma história inteira.','Sofia percebeu que dava para se divertir mesmo sem telas ligadas.'],perguntas:[{tipo:'multipla',enunciado:'O que Sofia fez quando a energia elétrica acabou?',opcoes:['Abriu as janelas e leu histórias com a irmã aproveitando a luz natural.','Ligou o ventilador e a televisão.','Foi dormir e não acordou mais.'],correta:0,explicacao:'Ela abriu as janelas e leu histórias com a irmã enquanto havia claridade.'},{tipo:'multipla',enunciado:'O que causou a falta de energia?',opcoes:['Uma ventania derrubou um galho sobre a fiação','Uma chuva de granizo','A conta não foi paga'],correta:0,explicacao:'O galho caiu sobre a fiação e a energia acabou na rua.'},{tipo:'inferencia',enunciado:'O que Sofia percebeu no fim da tarde?',opcoes:['Que dá para se divertir sem telas ligadas','Que não existe diversão sem televisão','Que ler é chato'],correta:0,explicacao:'Ela percebeu que dava para se divertir mesmo sem telas.'}]},
{id:'historia-52',titulo:'O troco na banca de revistas e jornais',autor:'Domínio público',anoEscolar:3,habilidadesBNCC:['EF02LP26','EF15LP04'],nivel:3,emoji:'💵',corFundo:'linear-gradient(135deg,#ffe8cc,#fff3d6)',texto:['Otávio juntou moedas e notas durante duas semanas para comprar um gibi que queria muito ler.','Chegou à banca com o dinheiro contado na mão e escolheu o exemplar da prateleira.','O gibi custava quinze reais, e Otávio entregou uma nota de vinte reais ao atendente.','Enquanto esperava o troco, conferiu mentalmente quanto deveria sobrar.','Ele recebeu cinco reais de troco, guardou no bolso com cuidado e abriu o gibi logo em seguida.','Saiu feliz, sabendo que tinha feito a conta direitinho.'],perguntas:[{tipo:'multipla',enunciado:'Quanto Otávio recebeu de troco ao pagar R$ 20,00 por um gibi de R$ 15,00?',opcoes:['R$ 5,00.','R$ 15,00.','R$ 25,00.'],correta:0,explicacao:'A diferença entre R$ 20,00 e R$ 15,00 é R$ 5,00.'},{tipo:'multipla',enunciado:'Quanto tempo Otávio levou juntando dinheiro?',opcoes:['Um dia','Duas semanas','Um ano'],correta:1,explicacao:'Ele juntou moedas e notas durante duas semanas.'},{tipo:'inferencia',enunciado:'Por que Otávio saiu feliz da banca?',opcoes:['Porque conseguiu o gibi e conferiu que o troco estava certo','Porque não pagou nada','Porque a banca fechou'],correta:0,explicacao:'Ele comprou o gibi e sabia que tinha feito a conta direitinho.'}]},
{id:'historia-53',titulo:'A pipa presa no galho baixo',autor:'Domínio público',anoEscolar:3,habilidadesBNCC:['EF02LP26','EF15LP04'],nivel:3,emoji:'🪁',corFundo:'linear-gradient(135deg,#e0f0d0,#d6f5e3)',texto:['Durante uma tarde de vento bom, Bruno e o primo empinavam pipa no campo perto de casa.','A linha escapou de repente e a pipa acabou pousando em um galho baixo de uma árvore.','Bruno teve vontade de puxar a linha com força para tentar arrancar, mas o primo lembrou que isso podia rasgar o papel.','Eles decidiram esperar um pouco e olhar com calma.','Com uma vara comprida e sem pressa, conseguiram soltar a pipa sem estragar nada.','Enrolaram a linha direitinho e continuaram brincando com segurança.'],perguntas:[{tipo:'multipla',enunciado:'Por que o primo pediu para Bruno não puxar a linha com força?',opcoes:['Porque puxar com força podia rasgar o papel da pipa.','Porque a pipa era feita de ferro.','Porque já era de noite.'],correta:0,explicacao:'O segundo parágrafo explica que puxar com força podia rasgar o papel da pipa.'},{tipo:'multipla',enunciado:'Onde a pipa ficou presa?',opcoes:['Em um galho baixo de uma árvore','No telhado de casa','No fio de luz'],correta:0,explicacao:'A pipa pousou em um galho baixo de uma árvore.'},{tipo:'inferencia',enunciado:'O que ajudou a soltar a pipa sem estragar?',opcoes:['Uma vara comprida e calma','Um puxão forte','Uma tesoura'],correta:0,explicacao:'Eles usaram uma vara comprida, sem pressa.'}]},
{id:'historia-54',titulo:'A organização dos livros da estante',autor:'Domínio público',anoEscolar:3,habilidadesBNCC:['EF02LP26','EF15LP04'],nivel:3,emoji:'📚',corFundo:'linear-gradient(135deg,#dbeafe,#e0f0ff)',texto:['A estante do quarto de Lorena estava tão cheia que os livros ficavam empilhados de qualquer jeito.','Na hora de procurar um livro específico, ela demorava bastante e quase sempre bagunçava os outros.','Numa manhã livre, Lorena tirou todos os livros, limpou a poeira das prateleiras com um pano seco e separou os títulos por assunto.','Colocou os de histórias de um lado e os de ciências e jogos do outro.','Quando terminou, ficou fácil achar qualquer livro em poucos segundos.','Lorena sentiu que o quarto parecia mais organizado e convidativo.'],perguntas:[{tipo:'multipla',enunciado:'Como Lorena organizou os livros na estante?',opcoes:['Separou por assunto depois de limpar as prateleiras.','Jogou todos dentro de um saco no chão.','Misturou tudo sem limpar.'],correta:0,explicacao:'Ela limpou as prateleiras e separou os livros por assunto.'},{tipo:'multipla',enunciado:'Qual era o problema antes da arrumação?',opcoes:['Ela demorava para achar um livro e bagunçava os outros','Não havia livros','A estante era pequena demais para um livro'],correta:0,explicacao:'Os livros ficavam empilhados e ela demorava para procurar.'},{tipo:'inferencia',enunciado:'Qual foi o resultado da arrumação?',opcoes:['Ficou fácil achar qualquer livro em poucos segundos','Ela perdeu todos os livros','A estante quebrou'],correta:0,explicacao:'Depois de organizar, achar um livro ficou rápido.'}]},
{id:'historia-55',titulo:'A visita à horta comunitária',autor:'Domínio público',anoEscolar:3,habilidadesBNCC:['EF02LP26','EF15LP04'],nivel:3,emoji:'🥬',corFundo:'linear-gradient(135deg,#fde2f3,#ffe0e0)',texto:['Na sexta-feira, a professora levou a turma para conhecer a horta cuidada pelos moradores do bairro.','Havia canteiros de alface, coentro, pimentão e mudas recém-plantadas.','O responsável pela horta mostrou como a terra úmida e fofa ajuda as raízes a crescerem bem.','Os alunos fizeram perguntas e anotaram o que acharam mais interessante no caderno.','Na volta para a escola, a turma comentou sobre a importância de cuidar dos espaços coletivos.','Todos voltaram inspirados para cuidar melhor do jardim da escola.'],perguntas:[{tipo:'multipla',enunciado:'O que o responsável pela horta mostrou para os alunos?',opcoes:['Como a terra úmida e fofa ajuda as raízes das plantas a crescerem.','Como construir um prédio de dez andares.','Por que não se deve regar as plantas.'],correta:0,explicacao:'O segundo parágrafo destaca a explicação sobre a terra úmida e fofa para as raízes.'},{tipo:'multipla',enunciado:'Quem cuidava da horta?',opcoes:['Os moradores do bairro','Os alunos da turma','Uma empresa'],correta:0,explicacao:'A horta era cuidada pelos moradores do bairro.'},{tipo:'inferencia',enunciado:'O que a visita inspirou os alunos a fazer?',opcoes:['Cuidar melhor do jardim da escola','Arrancar as plantas','Fechar a horta'],correta:0,explicacao:'Todos voltaram inspirados para cuidar melhor do jardim da escola.'}]},
{id:'historia-56',titulo:'A receita do suco natural',autor:'Domínio público',anoEscolar:3,habilidadesBNCC:['EF02LP26','EF15LP04'],nivel:3,emoji:'🍊',corFundo:'linear-gradient(135deg,#ffe8cc,#fff3d6)',texto:['O dia estava quente e Pedro resolveu preparar um suco de laranja natural para dividir com a família.','Ele lavou bem as frutas na pia antes de cortar ao meio.','Com cuidado para não se machucar, espremeu as metades e coou o suco para tirar os bagaços.','Provou um pouquinho e viu que já estava docinho, sem precisar colocar açúcar.','Colocou jarras na mesa com copos para todos e serviu bem gelado.','A família elogiou o capricho de Pedro e aproveitou o refresco.'],perguntas:[{tipo:'multipla',enunciado:'Por que Pedro não precisou colocar açúcar no suco de laranja?',opcoes:['Porque provou e viu que o suco já estava docinho.','Porque o suco tinha ficado azedo demais.','Porque não havia água na cozinha.'],correta:0,explicacao:'O texto informa que ele provou o suco e percebeu que já estava docinho.'},{tipo:'multipla',enunciado:'O que Pedro fez antes de cortar as laranjas?',opcoes:['Lavou bem as frutas na pia','Colocou açúcar','Serviu o suco'],correta:0,explicacao:'Ele lavou bem as frutas antes de cortar ao meio.'},{tipo:'inferencia',enunciado:'Por que Pedro preparou o suco?',opcoes:['Porque o dia estava quente e queria dividir com a família','Porque estava doente','Porque ia vender o suco'],correta:0,explicacao:'O dia estava quente e ele quis dividir o suco com a família.'}]},
{id:'historia-57',titulo:'O ensaio da apresentação escolar',autor:'Domínio público',anoEscolar:3,habilidadesBNCC:['EF02LP26','EF15LP04'],nivel:3,emoji:'🎭',corFundo:'linear-gradient(135deg,#e0f0d0,#d6f5e3)',texto:['Faltava uma semana para a apresentação de teatro da escola, e o grupo ainda errava algumas falas na hora de entrar em cena.','Alguns ficavam nervosos e falavam rápido demais.','A professora pediu que todos respirassem fundo, falassem mais devagar e ouvissem uns aos outros com atenção.','Repetiram a cena duas vezes seguidas e o ritmo melhorou bastante.','Ao final do ensaio, o grupo percebeu que a calma fazia toda a diferença.','Todos saíram mais confiantes para o dia do espetáculo.'],perguntas:[{tipo:'multipla',enunciado:'O que ajudou o grupo a melhorar durante o ensaio de teatro?',opcoes:['Respirar fundo, falar mais devagar e ouvir os colegas com atenção.','Gritar o mais alto possível sem olhar para ninguém.','Cancelar a apresentação na véspera.'],correta:0,explicacao:'As orientações da professora para falar devagar e ouvir uns aos outros melhoraram o ensaio.'},{tipo:'multipla',enunciado:'Qual era o problema do grupo no começo?',opcoes:['Errava falas e alguns falavam rápido demais','Ninguém queria ensaiar','Não havia professora'],correta:0,explicacao:'O grupo errava falas e alguns falavam rápido por nervosismo.'},{tipo:'inferencia',enunciado:'Como o grupo se sentiu ao final do ensaio?',opcoes:['Mais confiante','Mais nervoso','Sem vontade de apresentar'],correta:0,explicacao:'Todos saíram mais confiantes para o espetáculo.'}]},
{id:'historia-58',titulo:'A coleta de tampinhas e garrafas',autor:'Domínio público',anoEscolar:3,habilidadesBNCC:['EF02LP26','EF15LP04'],nivel:3,emoji:'♻️',corFundo:'linear-gradient(135deg,#dbeafe,#e0f0ff)',texto:['Durante o mês, os alunos juntaram tampinhas plásticas e garrafas limpas em uma caixa grande na sala.','O objetivo era separar o material reciclável em vez de misturar com o lixo comum.','Toda sexta-feira, dois voluntários contavam o que havia sido arrecadado e separavam as tampinhas por cor.','Era um momento rápido de organização que envolvia toda a turma.','Ao fim do mês, a caixa estava cheia e pronta para ser encaminhada à reciclagem.','A turma comemorou o resultado do trabalho em equipe.'],perguntas:[{tipo:'multipla',enunciado:'Qual era o objetivo da caixa de tampinhas e garrafas na sala?',opcoes:['Separar o material reciclável em vez de misturar com o lixo comum.','Guardar brinquedos quebrados para jogar fora.','Encher de água para molhar o chão.'],correta:0,explicacao:'O primeiro parágrafo explica que o objetivo era separar o material reciclável do lixo comum.'},{tipo:'multipla',enunciado:'O que os voluntários faziam toda sexta-feira?',opcoes:['Contavam o material e separavam as tampinhas por cor','Jogavam tudo fora','Pintavam as garrafas'],correta:0,explicacao:'Eles contavam o arrecadado e separavam as tampinhas por cor.'},{tipo:'inferencia',enunciado:'Por que a turma comemorou no fim do mês?',opcoes:['Porque o trabalho em equipe deu resultado','Porque a caixa quebrou','Porque acabaram as aulas'],correta:0,explicacao:'A caixa ficou cheia, fruto do trabalho em equipe.'}]},
{id:'historia-59',titulo:'A carta para o primo distante',autor:'Domínio público',anoEscolar:3,habilidadesBNCC:['EF02LP26','EF15LP04'],nivel:3,emoji:'✉️',corFundo:'linear-gradient(135deg,#fde2f3,#ffe0e0)',texto:['Cauê queria contar para o primo que mora em outra cidade sobre o campeonato de futebol da escola.','Em vez de mandar só uma mensagem apressada, decidiu escrever uma carta caprichada.','Ele contou como foram os treinos, quem marcou o gol da vitória e o que tinha acontecido na comemoração.','No fim, fez duas perguntas sobre a escola do primo.','Leu tudo de novo para ver se fazia sentido e guardou num envelope com cuidado.','Ficou animado imaginando a reação do primo ao ler cada detalhe.'],perguntas:[{tipo:'multipla',enunciado:'O que Cauê escreveu no final da carta para o primo?',opcoes:['Duas perguntas sobre a escola do primo.','Uma lista de compras do supermercado.','A previsão do tempo do ano inteiro.'],correta:0,explicacao:'O segundo parágrafo diz que no fim ele fez duas perguntas sobre a escola do primo.'},{tipo:'multipla',enunciado:'Sobre o que Cauê queria contar ao primo?',opcoes:['O campeonato de futebol da escola','Uma viagem de avião','Uma festa de aniversário'],correta:0,explicacao:'Ele queria contar sobre o campeonato de futebol da escola.'},{tipo:'inferencia',enunciado:'Por que Cauê leu a carta de novo antes de guardar?',opcoes:['Para ver se fazia sentido','Porque não sabia ler','Porque queria rasgar'],correta:0,explicacao:'Ele releu para conferir se a carta fazia sentido.'}]},
{id:'historia-60',titulo:'O conserto da lâmpada do corredor',autor:'Domínio público',anoEscolar:3,habilidadesBNCC:['EF02LP26','EF15LP04'],nivel:3,emoji:'💡',corFundo:'linear-gradient(135deg,#ffe8cc,#fff3d6)',texto:['A lâmpada do corredor de casa estava piscando há dois dias e deixava a passagem escura à noite.','O pai avisou que ia trocar a lâmpada assim que desligasse o interruptor geral para ter segurança.','Larissa ajudou alcançando a lâmpada nova com as duas mãos, segurando pelo vidro com cuidado.','O pai colocou a peça no lugar e testou depois de religar a energia.','A luz acendeu firme e clara, iluminando todo o corredor sem piscar.','Larissa achou bom ver como pequenas tarefas ficam seguras quando feitas com atenção.'],perguntas:[{tipo:'multipla',enunciado:'O que o pai de Larissa fez antes de trocar a lâmpada para ter segurança?',opcoes:['Desligou a energia e o interruptor antes de mexer.','Subiu numa cadeira com os olhos vendados.','Jogou água na tomada.'],correta:0,explicacao:'O texto destaca que o cuidado com a segurança veio ao desligar antes de trocar.'},{tipo:'multipla',enunciado:'Qual era o problema da lâmpada do corredor?',opcoes:['Estava piscando há dois dias','Estava quebrada no chão','Estava muito forte'],correta:0,explicacao:'A lâmpada piscava há dois dias e deixava o corredor escuro.'},{tipo:'inferencia',enunciado:'O que Larissa percebeu no final?',opcoes:['Que tarefas pequenas ficam seguras quando feitas com atenção','Que lâmpadas nunca queimam','Que o corredor não precisa de luz'],correta:0,explicacao:'Ela achou bom ver como a atenção deixa as tarefas seguras.'}]},
{id:'historia-61',titulo:'A tarde de jogos de tabuleiro',autor:'Domínio público',anoEscolar:3,habilidadesBNCC:['EF02LP26','EF15LP04'],nivel:3,emoji:'🎯',corFundo:'linear-gradient(135deg,#e0f0d0,#d6f5e3)',texto:['Chovia forte lá fora, e quatro amigos se reuniram na sala para jogar um jogo de tabuleiro.','Antes de começar, leram juntos as regras rápidas para ninguém ter dúvida durante a partida.','Cada um esperava a sua vez de jogar o dado e mover o pino, ajudando quando alguém esquecia uma regra.','Mesmo quando a partida ficou disputada, o clima continuou amigável.','No fim da tarde, todos guardaram as peças na caixa para não perder nenhuma.','Combinaram de se reunir de novo no próximo sábado chuvoso.'],perguntas:[{tipo:'multipla',enunciado:'O que os amigos fizeram antes de começar a partida?',opcoes:['Leram juntos as regras rápidas do jogo.','Esconderam todas as peças da caixa.','Foram embora antes de jogar.'],correta:0,explicacao:'O primeiro parágrafo informa que leram juntos as regras rápidas antes de começar.'},{tipo:'multipla',enunciado:'Quantos amigos jogaram?',opcoes:['Dois','Quatro','Dez'],correta:1,explicacao:'O texto diz que quatro amigos se reuniram na sala.'},{tipo:'inferencia',enunciado:'Por que guardaram as peças na caixa no fim?',opcoes:['Para não perder nenhuma','Para jogar fora','Para esconder da chuva'],correta:0,explicacao:'Guardar na caixa evita perder peças.'}]}
];
